# --- Workflow 3: Infra validate (Terraform + Packer, validate-only) ---------
# New workflow per the infra-validate design decision (design.include_ci_validate_workflow
# = true): a permanent, standing CI check that the Terraform (GitHub-provider
# module under infra/terraform/github, plus the existing infra/gcp/cloudrun
# module) and Packer (infra/gcp/packer) configuration this repo carries is
# real, well-formed HCL -- never previously exercised by any CI workflow.
#
# VALIDATE-ONLY, by construction, satisfying gate 020_security.rq without
# any performsOperation-derivation dance: permissionCeiling is "contents:
# read" only, no write scope of any kind is granted, and every runCommand
# below is exactly `terraform init -backend=false` / `terraform validate` or
# `packer init` / `packer validate` -- never `terraform apply`, never a
# `terraform plan` against a real backend, never `packer build`. Zero cloud
# credentials are read, required, or consumed anywhere in this workflow.
#
# Action pins resolved for real via `git ls-remote --tags` on 2026-08-30 (not
# assumed), the same verification discipline as Workflows 1/2 above:
#   - actions/checkout reuses the exact d23441a4...af803 SHA already verified
#     and in production for bex:ciCheckout / bex:containerCheckout in this
#     same file.
#   - hashicorp/setup-terraform -> b9cd54a3c349d3f38e8881555d616ced269862dd,
#     tag v3.1.2 (newest v3.x tag at resolution time).
#   - hashicorp/setup-packer -> ce93c3c08a6c2ff2275bf4b54ff0d9a75f6c9789, tag
#     v3.4.0 -- `git ls-remote` confirms this is the identical commit the
#     floating "v3" tag also points at.
#
# infra/terraform/github does not exist in this checkout yet -- it is the
# output of a separate, not-yet-landed gh-terraform-pack workstream from the
# same design. The terraform step below still names and covers that path (the
# task instruction this fragment was drafted for: "any newly-added
# GitHub-provider Terraform module path, if you can determine it from
# context"), guarded by a directory-existence check so this workflow does not
# hard-fail before that module lands; once it does, no further ontology
# change is needed for the gate to start covering it for real.

bex:infraValidateWorkflow
    a gha:Workflow ;
    gha:fileName "beam4pm-infra-validate.yml" ;
    gha:purpose "beam4pm Infra Validate (Terraform + Packer, validate-only)" ;
    gha:permissionCeiling "contents: read" ;
    gha:trigger gha:EventPush ;
    gha:trigger gha:EventPullRequest ;
    gha:trigger gha:EventWorkflowDispatch ;
    gha:onBlock """push:
  branches: [main]
  paths:
    - "infra/**"
    - "ontology.ttl"
    - "vendor/ggen-marketplace/packs/gh-terraform-pack/**"
    - "vendor/ggen-marketplace/packs/beam4pm-pro-infra-pack/**"
pull_request:
  branches: [main]
  paths:
    - "infra/**"
    - "ontology.ttl"
    - "vendor/ggen-marketplace/packs/gh-terraform-pack/**"
    - "vendor/ggen-marketplace/packs/beam4pm-pro-infra-pack/**"
workflow_dispatch:""" ;
    gha:evidenceObligation "a clean terraform init -backend=false + terraform validate for every Terraform module under infra/ (infra/gcp/cloudrun and, once it lands, infra/terraform/github), and a clean packer init + packer validate for infra/gcp/packer, all against the exact candidate SHA" ;
    gha:standingEffect "a green run confers syntactic/semantic HCL-validity standing only -- no plan, no apply, no cloud credentials consumed, no remote state read or written. It proves the committed Terraform and Packer configuration is well-formed and internally consistent; it never proves a real apply/build against live GCP would succeed." .

bex:infraValidateJob
    a gha:Job ;
    gha:inWorkflow bex:infraValidateWorkflow ;
    gha:jobName "validate" ;
    gha:runner "ubuntu-latest" ;
    gha:timeoutMinutes 15 ;
    gha:jobExtra "name: Terraform + Packer validate (no apply, no build, zero cloud credentials)" ;
    gha:evidenceEmitted "terraform validate and packer validate output (both exit 0) in the run log for every module listed above" ;
    gha:failureClassification "a red run is either a real HCL syntax/reference defect in the committed configuration or a stale/incompatible provider version pin -- never a live-infrastructure fault, since no apply or build ever executes." .

bex:infraValidateCheckout
    a gha:Step ;
    gha:inJob bex:infraValidateJob ; gha:stepOrder 1 ;
    gha:stepName "Checkout" ;
    gha:usesAction "actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6" ;
    gha:withParam "persist-credentials: false" .

bex:infraValidateSetupTerraform
    a gha:Step ;
    gha:inJob bex:infraValidateJob ; gha:stepOrder 2 ;
    gha:stepName "Set up Terraform" ;
    gha:usesAction "hashicorp/setup-terraform@b9cd54a3c349d3f38e8881555d616ced269862dd # v3.1.2" ;
    gha:withParam "terraform_wrapper: false" .

bex:infraValidateSetupPacker
    a gha:Step ;
    gha:inJob bex:infraValidateJob ; gha:stepOrder 3 ;
    gha:stepName "Set up Packer" ;
    gha:usesAction "hashicorp/setup-packer@ce93c3c08a6c2ff2275bf4b54ff0d9a75f6c9789 # v3.4.0" ;
    gha:withParam "version: 'latest'" .

bex:infraValidateTerraformInitValidate
    a gha:Step ;
    gha:inJob bex:infraValidateJob ; gha:stepOrder 4 ;
    gha:stepName "terraform init -backend=false + terraform validate (all infra/ Terraform modules)" ;
    gha:runCommand """set -euo pipefail
for d in infra/gcp/cloudrun infra/terraform/github; do
  if [ ! -d "$d" ]; then
    echo "== skip (not present yet): $d =="
    continue
  fi
  echo "== terraform init/validate: $d =="
  terraform -chdir="$d" init -backend=false -input=false
  terraform -chdir="$d" validate
done""" .

bex:infraValidatePackerInitValidate
    a gha:Step ;
    gha:inJob bex:infraValidateJob ; gha:stepOrder 5 ;
    gha:stepName "packer init + packer validate (infra/gcp/packer)" ;
    gha:runCommand """set -euo pipefail
packer init infra/gcp/packer
packer validate infra/gcp/packer""" .

# =============================================================================
# beam4pm's own GitHub repo management (gh-terraform-pack) instance data
# =============================================================================
# Manages seanchatmangpt/beam4pm itself (repository/milestones/labels/issues)
# via gh-terraform-pack v0.2.0 (vendor/ggen-marketplace/packs/gh-terraform-pack,
# wired in ggen.toml under [packs] as gh-terraform-pack). Zero ManagedRepo/
# secrets/branch-protection/rulesets/environments/webhooks are declared here --
# none were requested and gates/020_fleet.rq + gates/030_policy.rq Rules 1/3
# only engage on ghtf:ManagedRepo subjects, which this file never declares.
#
# Zero-AWS backend: gh-terraform-pack's root infra/terraform/github/backend.tf
# (backend_tf.tmpl) hardcodes ghtf:S3DynamoBackend's literal AWS S3+DynamoDB
# body with no ghtf:backendKind dispatch -- a disclosed, unfixed pack gap, left
# inert and never initialized. The pack's only supported non-AWS backend route
# is org-scoped (ghtf:forOrg + one ghtf:OrgTenant), so one minimally-scoped
# OrgTenant is declared below purely to key a real GCS-flavored per-org backend
# file (org_backend_tf.tmpl -> infra/terraform/github/orgs/beam4pm/backend.tf).
# It deliberately OMITS ghtf:orgOwner/ghtf:appAuthVarPrefix: org_providers_tf.tmpl
# requires all three (orgAlias+orgOwner+appAuthVarPrefix, non-OPTIONAL triple
# pattern) to emit a `provider "github" { alias = ... app_auth { ... } }` block,
# and that block would reference var.<prefix>_app_id / _app_installation_id /
# _app_pem_file variables this pack's fixed, pre-baked variables.tf never
# declares -- terraform validate would fail on undefined variable references.
# Omitting those two predicates makes that query's basic graph pattern match
# zero rows for this org, so root providers.tf stays header-only for it while
# org_backend_tf.tmpl (which only needs orgAlias) still fires correctly.
@prefix ghtf: <http://seanchatmangpt.github.io/packs/gh-terraform#> .
@prefix bgt:  <https://ggen.dev/beam4pm/github-terraform#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

bgt:BeamOrgTenant a ghtf:OrgTenant ;
    rdfs:label "beam4pm's own GitHub org tenant (github.com/seanchatmangpt), minimally-scoped: exists solely to key the GCS-flavored org-scoped backend file below, not to opt into multi-org provider aliasing (see section comment)." ;
    ghtf:orgAlias "beam4pm" ;
    ghtf:ssoRequired false .

bgt:BeamGcsBackend a ghtf:BackendConfig ;
    rdfs:label "GCS remote state for beam4pm's own GitHub-management Terraform module -- the real, zero-AWS backend this module actually uses; the root backend.tf's AWS S3+DynamoDB body stays a disclosed, inert, unfixed pack gap (see section comment)." ;
    ghtf:backendKind "gcs" ;
    ghtf:forOrg bgt:BeamOrgTenant ;
    ghtf:requiredArg "bucket", "prefix" ;
    ghtf:hclBody """terraform {
  backend "gcs" {
    bucket = "beam4pm-terraform-state"
    prefix = "org-management/github/orgs/beam4pm"
  }
}
""" .

