    ghtf:hclBody """resource "github_issue" "mirror_ghcr_artifact_registry" {
  repository = var.repository
  title      = "Mirror the GHCR beam4pm container image into a GCP Artifact Registry repository"
  body       = <<EOT
Two independent docs name this as a real blocking prerequisite:

